K = input

def f(x, pre):
	q = deque([(x, pre)])
	dp = [0] * (n + 1)
	R = []
	while q:
		(u, p) = q.popleft()
		R.append(u)
		for v in g[u]:
			if v != p:
				g[v].remove(u)
				q.append((v, u))
	for u in R[::-1]:
		z = c = 0
		for v in g[u]:
			z += dp[v]
			if dp[v] == 0:
				c += 1
			dp[u] = z + max(0, c - 1)
	return dp[x]
